public async Task<Result> UpdateAsync(int docId, DocPatch patch, CancellationToken ct)
{
    var doc = await _repo.GetAsync(docId, ct);
    if (doc is null) return Result.NotFound();
    if (!_authz.CanEdit(_user, doc)) return Result.Forbidden();
    doc.Apply(patch);
    return await _repo.SaveAsync(doc, ct);
}
